-- Minimal structural fixture copied from the production table's audited
-- relevant columns and types. Isolated in a dedicated disposable schema.
CREATE SCHEMA IF NOT EXISTS pr_d_test;
CREATE TABLE pr_d_test.youtube_shorts_log (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    youtube_video_id text NOT NULL,
    views_primeras_3h integer,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
